Sub 'PrintFilters'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
If &GridState.DynamicFilters.Count >= 1 &GridStateDynamicFilter = &GridState.DynamicFilters.Item(1) &DynamicFiltersSelector1 = &GridStateDynamicFilter.Selected Do Case Case &DynamicFiltersSelector1 = !'FORNOME' &DynamicFiltersOperator1 = &GridStateDynamicFilter.Operator &forNome1.FromString(&GridStateDynamicFilter.Value) If not &forNome1.IsEmpty() Do Case Case &DynamicFiltersOperator1 = 0 &FilterforNomeDescription = format('%1 (%2)', "Nome", "WWP_FilterContains") Case &DynamicFiltersOperator1 = 1 &FilterforNomeDescription = format('%1 (%2)', "Nome", "WWP_FilterLike") EndCase &forNome = &forNome1 print printBlockFilterforNome EndIf Case &DynamicFiltersSelector1 = !'FORCODIGO' &DynamicFiltersOperator1 = &GridStateDynamicFilter.Operator &forCodigo1.FromString(&GridStateDynamicFilter.Value) If not &forCodigo1.IsEmpty() Do Case Case &DynamicFiltersOperator1 = 0 &FilterforCodigoDescription = format('%1 (%2)', "Código", "=") EndCase &forCodigo = &forCodigo1 print printBlockFilterforCodigo EndIf Case &DynamicFiltersSelector1 = !'FORCIDADE' &DynamicFiltersOperator1 = &GridStateDynamicFilter.Operator &forCidade1.FromString(&GridStateDynamicFilter.Value) If not &forCidade1.IsEmpty() Do Case Case &DynamicFiltersOperator1 = 0 &FilterforCidadeDescription = format('%1 (%2)', "Cidade", "WWP_FilterContains") Case &DynamicFiltersOperator1 = 1 &FilterforCidadeDescription = format('%1 (%2)', "Cidade", "WWP_FilterLike") EndCase &forCidade = &forCidade1 print printBlockFilterforCidade EndIf Case &DynamicFiltersSelector1 = !'FORCNPJCPF' &DynamicFiltersOperator1 = &GridStateDynamicFilter.Operator &forCnpjcpf1.FromString(&GridStateDynamicFilter.Value) If not &forCnpjcpf1.IsEmpty() Do Case Case &DynamicFiltersOperator1 = 0 &FilterforCnpjcpfDescription = format('%1 (%2)', "CNPJ ou CPF", "WWP_FilterContains") Case &DynamicFiltersOperator1 = 1 &FilterforCnpjcpfDescription = format('%1 (%2)', "CNPJ ou CPF", "WWP_FilterLike") EndCase &forCnpjcpf = &forCnpjcpf1 print printBlockFilterforCnpjcpf EndIf Case &DynamicFiltersSelector1 = !'FOREMAIL' &DynamicFiltersOperator1 = &GridStateDynamicFilter.Operator &forEmail1.FromString(&GridStateDynamicFilter.Value) If not &forEmail1.IsEmpty() Do Case Case &DynamicFiltersOperator1 = 0 &FilterforEmailDescription = format('%1 (%2)', "Email", "WWP_FilterContains") Case &DynamicFiltersOperator1 = 1 &FilterforEmailDescription = format('%1 (%2)', "Email", "WWP_FilterLike") EndCase &forEmail = &forEmail1 print printBlockFilterforEmail EndIf Case &DynamicFiltersSelector1 = !'FORBAIRRO' &DynamicFiltersOperator1 = &GridStateDynamicFilter.Operator &forBairro1.FromString(&GridStateDynamicFilter.Value) If not &forBairro1.IsEmpty() Do Case Case &DynamicFiltersOperator1 = 0 &FilterforBairroDescription = format('%1 (%2)', "Bairro", "WWP_FilterContains") Case &DynamicFiltersOperator1 = 1 &FilterforBairroDescription = format('%1 (%2)', "Bairro", "WWP_FilterLike") EndCase &forBairro = &forBairro1 print printBlockFilterforBairro EndIf Case &DynamicFiltersSelector1 = !'FORTELEFONE' &DynamicFiltersOperator1 = &GridStateDynamicFilter.Operator &forTelefone1.FromString(&GridStateDynamicFilter.Value) If not &forTelefone1.IsEmpty() Do Case Case &DynamicFiltersOperator1 = 0 &FilterforTelefoneDescription = format('%1 (%2)', "Telefone", "WWP_FilterContains") Case &DynamicFiltersOperator1 = 1 &FilterforTelefoneDescription = format('%1 (%2)', "Telefone", "WWP_FilterLike") EndCase &forTelefone = &forTelefone1 print printBlockFilterforTelefone EndIf EndCase If &GridState.DynamicFilters.Count >= 2 &DynamicFiltersEnabled2 = True &GridStateDynamicFilter = &GridState.DynamicFilters.Item(2) &DynamicFiltersSelector2 = &GridStateDynamicFilter.Selected Do Case Case &DynamicFiltersSelector2 = !'FORNOME' &DynamicFiltersOperator2 = &GridStateDynamicFilter.Operator &forNome2.FromString(&GridStateDynamicFilter.Value) If not &forNome2.IsEmpty() Do Case Case &DynamicFiltersOperator2 = 0 &FilterforNomeDescription = format('%1 (%2)', "Nome", "WWP_FilterContains") Case &DynamicFiltersOperator2 = 1 &FilterforNomeDescription = format('%1 (%2)', "Nome", "WWP_FilterLike") EndCase &forNome = &forNome2 print printBlockFilterforNome EndIf Case &DynamicFiltersSelector2 = !'FORCODIGO' &DynamicFiltersOperator2 = &GridStateDynamicFilter.Operator &forCodigo2.FromString(&GridStateDynamicFilter.Value) If not &forCodigo2.IsEmpty() Do Case Case &DynamicFiltersOperator2 = 0 &FilterforCodigoDescription = format('%1 (%2)', "Código", "=") EndCase &forCodigo = &forCodigo2 print printBlockFilterforCodigo EndIf Case &DynamicFiltersSelector2 = !'FORCIDADE' &DynamicFiltersOperator2 = &GridStateDynamicFilter.Operator &forCidade2.FromString(&GridStateDynamicFilter.Value) If not &forCidade2.IsEmpty() Do Case Case &DynamicFiltersOperator2 = 0 &FilterforCidadeDescription = format('%1 (%2)', "Cidade", "WWP_FilterContains") Case &DynamicFiltersOperator2 = 1 &FilterforCidadeDescription = format('%1 (%2)', "Cidade", "WWP_FilterLike") EndCase &forCidade = &forCidade2 print printBlockFilterforCidade EndIf Case &DynamicFiltersSelector2 = !'FORCNPJCPF' &DynamicFiltersOperator2 = &GridStateDynamicFilter.Operator &forCnpjcpf2.FromString(&GridStateDynamicFilter.Value) If not &forCnpjcpf2.IsEmpty() Do Case Case &DynamicFiltersOperator2 = 0 &FilterforCnpjcpfDescription = format('%1 (%2)', "CNPJ ou CPF", "WWP_FilterContains") Case &DynamicFiltersOperator2 = 1 &FilterforCnpjcpfDescription = format('%1 (%2)', "CNPJ ou CPF", "WWP_FilterLike") EndCase &forCnpjcpf = &forCnpjcpf2 print printBlockFilterforCnpjcpf EndIf Case &DynamicFiltersSelector2 = !'FOREMAIL' &DynamicFiltersOperator2 = &GridStateDynamicFilter.Operator &forEmail2.FromString(&GridStateDynamicFilter.Value) If not &forEmail2.IsEmpty() Do Case Case &DynamicFiltersOperator2 = 0 &FilterforEmailDescription = format('%1 (%2)', "Email", "WWP_FilterContains") Case &DynamicFiltersOperator2 = 1 &FilterforEmailDescription = format('%1 (%2)', "Email", "WWP_FilterLike") EndCase &forEmail = &forEmail2 print printBlockFilterforEmail EndIf Case &DynamicFiltersSelector2 = !'FORBAIRRO' &DynamicFiltersOperator2 = &GridStateDynamicFilter.Operator &forBairro2.FromString(&GridStateDynamicFilter.Value) If not &forBairro2.IsEmpty() Do Case Case &DynamicFiltersOperator2 = 0 &FilterforBairroDescription = format('%1 (%2)', "Bairro", "WWP_FilterContains") Case &DynamicFiltersOperator2 = 1 &FilterforBairroDescription = format('%1 (%2)', "Bairro", "WWP_FilterLike") EndCase &forBairro = &forBairro2 print printBlockFilterforBairro EndIf Case &DynamicFiltersSelector2 = !'FORTELEFONE' &DynamicFiltersOperator2 = &GridStateDynamicFilter.Operator &forTelefone2.FromString(&GridStateDynamicFilter.Value) If not &forTelefone2.IsEmpty() Do Case Case &DynamicFiltersOperator2 = 0 &FilterforTelefoneDescription = format('%1 (%2)', "Telefone", "WWP_FilterContains") Case &DynamicFiltersOperator2 = 1 &FilterforTelefoneDescription = format('%1 (%2)', "Telefone", "WWP_FilterLike") EndCase &forTelefone = &forTelefone2 print printBlockFilterforTelefone EndIf EndCase If &GridState.DynamicFilters.Count >= 3 &DynamicFiltersEnabled3 = True &GridStateDynamicFilter = &GridState.DynamicFilters.Item(3) &DynamicFiltersSelector3 = &GridStateDynamicFilter.Selected Do Case Case &DynamicFiltersSelector3 = !'FORNOME' &DynamicFiltersOperator3 = &GridStateDynamicFilter.Operator &forNome3.FromString(&GridStateDynamicFilter.Value) If not &forNome3.IsEmpty() Do Case Case &DynamicFiltersOperator3 = 0 &FilterforNomeDescription = format('%1 (%2)', "Nome", "WWP_FilterContains") Case &DynamicFiltersOperator3 = 1 &FilterforNomeDescription = format('%1 (%2)', "Nome", "WWP_FilterLike") EndCase &forNome = &forNome3 print printBlockFilterforNome EndIf Case &DynamicFiltersSelector3 = !'FORCODIGO' &DynamicFiltersOperator3 = &GridStateDynamicFilter.Operator &forCodigo3.FromString(&GridStateDynamicFilter.Value) If not &forCodigo3.IsEmpty() Do Case Case &DynamicFiltersOperator3 = 0 &FilterforCodigoDescription = format('%1 (%2)', "Código", "=") EndCase &forCodigo = &forCodigo3 print printBlockFilterforCodigo EndIf Case &DynamicFiltersSelector3 = !'FORCIDADE' &DynamicFiltersOperator3 = &GridStateDynamicFilter.Operator &forCidade3.FromString(&GridStateDynamicFilter.Value) If not &forCidade3.IsEmpty() Do Case Case &DynamicFiltersOperator3 = 0 &FilterforCidadeDescription = format('%1 (%2)', "Cidade", "WWP_FilterContains") Case &DynamicFiltersOperator3 = 1 &FilterforCidadeDescription = format('%1 (%2)', "Cidade", "WWP_FilterLike") EndCase &forCidade = &forCidade3 print printBlockFilterforCidade EndIf Case &DynamicFiltersSelector3 = !'FORCNPJCPF' &DynamicFiltersOperator3 = &GridStateDynamicFilter.Operator &forCnpjcpf3.FromString(&GridStateDynamicFilter.Value) If not &forCnpjcpf3.IsEmpty() Do Case Case &DynamicFiltersOperator3 = 0 &FilterforCnpjcpfDescription = format('%1 (%2)', "CNPJ ou CPF", "WWP_FilterContains") Case &DynamicFiltersOperator3 = 1 &FilterforCnpjcpfDescription = format('%1 (%2)', "CNPJ ou CPF", "WWP_FilterLike") EndCase &forCnpjcpf = &forCnpjcpf3 print printBlockFilterforCnpjcpf EndIf Case &DynamicFiltersSelector3 = !'FOREMAIL' &DynamicFiltersOperator3 = &GridStateDynamicFilter.Operator &forEmail3.FromString(&GridStateDynamicFilter.Value) If not &forEmail3.IsEmpty() Do Case Case &DynamicFiltersOperator3 = 0 &FilterforEmailDescription = format('%1 (%2)', "Email", "WWP_FilterContains") Case &DynamicFiltersOperator3 = 1 &FilterforEmailDescription = format('%1 (%2)', "Email", "WWP_FilterLike") EndCase &forEmail = &forEmail3 print printBlockFilterforEmail EndIf Case &DynamicFiltersSelector3 = !'FORBAIRRO' &DynamicFiltersOperator3 = &GridStateDynamicFilter.Operator &forBairro3.FromString(&GridStateDynamicFilter.Value) If not &forBairro3.IsEmpty() Do Case Case &DynamicFiltersOperator3 = 0 &FilterforBairroDescription = format('%1 (%2)', "Bairro", "WWP_FilterContains") Case &DynamicFiltersOperator3 = 1 &FilterforBairroDescription = format('%1 (%2)', "Bairro", "WWP_FilterLike") EndCase &forBairro = &forBairro3 print printBlockFilterforBairro EndIf Case &DynamicFiltersSelector3 = !'FORTELEFONE' &DynamicFiltersOperator3 = &GridStateDynamicFilter.Operator &forTelefone3.FromString(&GridStateDynamicFilter.Value) If not &forTelefone3.IsEmpty() Do Case Case &DynamicFiltersOperator3 = 0 &FilterforTelefoneDescription = format('%1 (%2)', "Telefone", "WWP_FilterContains") Case &DynamicFiltersOperator3 = 1 &FilterforTelefoneDescription = format('%1 (%2)', "Telefone", "WWP_FilterLike") EndCase &forTelefone = &forTelefone3 print printBlockFilterforTelefone EndIf EndCase EndIf EndIf EndIf If not (&TFforCodigo.IsEmpty() AND &TFforCodigo_To.IsEmpty()) print printBlockTFforCodigo &TFforCodigo_To_Description = format('%1 (%2)', "Código", "WWP_TSTo") print printBlockTFforCodigo_To EndIf If not &TFforNome_Sel.IsEmpty() print printBlockTFforNome_Sel Else If not &TFforNome.IsEmpty() print printBlockTFforNome EndIf EndIf If not &TFforContato_Sel.IsEmpty() print printBlockTFforContato_Sel Else If not &TFforContato.IsEmpty() print printBlockTFforContato EndIf EndIf If not &TFforCnpjcpf_Sel.IsEmpty() print printBlockTFforCnpjcpf_Sel Else If not &TFforCnpjcpf.IsEmpty() print printBlockTFforCnpjcpf EndIf EndIf If not &TFforCidade_Sel.IsEmpty() print printBlockTFforCidade_Sel Else If not &TFforCidade.IsEmpty() print printBlockTFforCidade EndIf EndIf If not &TFforEstado_Sel.IsEmpty() print printBlockTFforEstado_Sel Else If not &TFforEstado.IsEmpty() print printBlockTFforEstado EndIf EndIf If not &TFforTelefone_Sel.IsEmpty() print printBlockTFforTelefone_Sel Else If not &TFforTelefone.IsEmpty() print printBlockTFforTelefone EndIf EndIf If not &TFforEmail_Sel.IsEmpty() print printBlockTFforEmail_Sel Else If not &TFforEmail.IsEmpty() print printBlockTFforEmail EndIf EndIf &TFforStatus_Sels.FromJson(&TFforStatus_SelsJson) If not &TFforStatus_Sels.Count = 0 &i = 1 For &TFforStatus_Sel in &TFforStatus_Sels If &i = 1 &TFforStatus_SelDscs = '' Else &TFforStatus_SelDscs += ', ' EndIf &FilterTFforStatus_SelValueDescription = '' Do Case Case &TFforStatus_Sel.ToString().Trim() = !"A" &FilterTFforStatus_SelValueDescription = "Ativo"
Case &TFforStatus_Sel.ToString().Trim() = !"I" &FilterTFforStatus_SelValueDescription = "Inativo"
EndCase
&TFforStatus_SelDscs += &FilterTFforStatus_SelValueDescription &i += 1 EndFor print printBlockTFforStatus_Sel EndIf
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'PrintColumnTitles'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
print printBlockBeforeGrid print printBlockLines_titles
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'PrintData'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
For each trnsfornecedores order forCodigo when &OrderedBy = 1 AND &OrderedDsc = False order (forCodigo) when &OrderedBy = 1 AND &OrderedDsc = True order forNome when &OrderedBy = 2 AND &OrderedDsc = False order (forNome) when &OrderedBy = 2 AND &OrderedDsc = True order forContato when &OrderedBy = 3 AND &OrderedDsc = False order (forContato) when &OrderedBy = 3 AND &OrderedDsc = True order forCnpjcpf when &OrderedBy = 4 AND &OrderedDsc = False order (forCnpjcpf) when &OrderedBy = 4 AND &OrderedDsc = True order forCidade when &OrderedBy = 5 AND &OrderedDsc = False order (forCidade) when &OrderedBy = 5 AND &OrderedDsc = True order forEstado when &OrderedBy = 6 AND &OrderedDsc = False order (forEstado) when &OrderedBy = 6 AND &OrderedDsc = True order forTelefone when &OrderedBy = 7 AND &OrderedDsc = False order (forTelefone) when &OrderedBy = 7 AND &OrderedDsc = True order forEmail when &OrderedBy = 8 AND &OrderedDsc = False order (forEmail) when &OrderedBy = 8 AND &OrderedDsc = True order forStatus when &OrderedBy = 9 AND &OrderedDsc = False order (forStatus) when &OrderedBy = 9 AND &OrderedDsc = True
using trnsfornecedoresWWDS(&DynamicFiltersSelector1, &DynamicFiltersOperator1, &forNome1, &forCodigo1, &forCidade1, &forCnpjcpf1 , &forEmail1, &forBairro1, &forTelefone1, &DynamicFiltersEnabled2, &DynamicFiltersSelector2, &DynamicFiltersOperator2 , &forNome2, &forCodigo2, &forCidade2, &forCnpjcpf2, &forEmail2, &forBairro2 , &forTelefone2, &DynamicFiltersEnabled3, &DynamicFiltersSelector3, &DynamicFiltersOperator3, &forNome3, &forCodigo3 , &forCidade3, &forCnpjcpf3, &forEmail3, &forBairro3, &forTelefone3, &TFforCodigo , &TFforCodigo_To, &TFforNome, &TFforNome_Sel, &TFforContato, &TFforContato_Sel, &TFforCnpjcpf , &TFforCnpjcpf_Sel, &TFforCidade, &TFforCidade_Sel, &TFforEstado, &TFforEstado_Sel, &TFforTelefone , &TFforTelefone_Sel, &TFforEmail, &TFforEmail_Sel, &TFforStatus_Sels) Where prefCodigo = &prefCodigo &forStatusDescription = '' Do Case Case forStatus.ToString().Trim() = !"A" &forStatusDescription = "Ativo"
Case forStatus.ToString().Trim() = !"I" &forStatusDescription = "Inativo"
EndCase
Do 'BeforePrintLine' print printBlockLines_data Do 'AfterPrintLine' EndFor
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'LoadGridState'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
// Load grid state from session. If &Session.Get(!"trnsfornecedoresWWGridState") = !"" &GridState.FromXml(LoadGridState.Udp(!"trnsfornecedoresWWGridState")) Else &GridState.FromXml(&Session.Get(!"trnsfornecedoresWWGridState")) Endif
&OrderedBy = &GridState.OrderedBy &OrderedDsc = &GridState.OrderedDsc
For &GridStateFilterValue in &GridState.FilterValues Do Case Case &GridStateFilterValue.Name = !"TFFORCODIGO" &TFforCodigo.FromString(&GridStateFilterValue.Value) &TFforCodigo_To.FromString(&GridStateFilterValue.ValueTo) Case &GridStateFilterValue.Name = !"TFFORNOME" &TFforNome.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFFORNOME_SEL" &TFforNome_Sel.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFFORCONTATO" &TFforContato.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFFORCONTATO_SEL" &TFforContato_Sel.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFFORCNPJCPF" &TFforCnpjcpf.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFFORCNPJCPF_SEL" &TFforCnpjcpf_Sel.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFFORCIDADE" &TFforCidade.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFFORCIDADE_SEL" &TFforCidade_Sel.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFFORESTADO" &TFforEstado.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFFORESTADO_SEL" &TFforEstado_Sel.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFFORTELEFONE" &TFforTelefone.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFFORTELEFONE_SEL" &TFforTelefone_Sel.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFFOREMAIL" &TFforEmail.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFFOREMAIL_SEL" &TFforEmail_Sel.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFFORSTATUS_SEL" &TFforStatus_SelsJson = &GridStateFilterValue.Value &TFforStatus_Sels.FromJson(&TFforStatus_SelsJson) EndCase EndFor
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
